head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gDepCd;
scwin.gUpDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gRsnClssCdList = "";
scwin.gScnNm;
scwin.gKeyword;
scwin.pageSize = 50; //페이지 size
scwin.totalCnt = 0; //전체 row
scwin.pageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호

scwin.gExcelTp = "1";
scwin.vScrenID = 'ULDSTF15002.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    scwin.gUpDepCd = js_belngdepcd;
    $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    if (scwin.gLdMktTp == '1' || scwin.gLdMktTp == '2' || scwin.gLdMktTp == '6') {
        // 코넥스 추가
        $c.stf.showObj(panel_mkt, false);
    }

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.     
    // 코넥스 추가
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34' || js_dep_cd.substring(0, 2) == '3B') {
        $c.stf.showObj(panel_dep_emp, true);
        scwin.gDepCd = "UPTEAM";
    } else {
        $c.stf.showObj(panel_dep_emp, false);
    }

    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    //edt_FromDate.text = cGetMinusDate2(vCurDate, 7); 	// 일주일전 날짜
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_emp.Reset();

    // 업종 셋팅
    dts_IndTp.DataID = "/CodeAction.do?method=listStdIndtpCB" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&For=R";
    dts_IndTp.Reset();
};


// 법인명이 있고 특정 다른 조건을 선택할때 메세지
scwin.fn_CheckComNmCond = function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    if (vIsurCd != '') {
        $c.win.alert("해당항목 선택시 법인코드(명)의 조건값이  초기화 됩니다.");
        $c.stf.setObjectValue(txb_isur_cd, '');
        $c.stf.setObjectValue(txb_com_abbrv, '');
        return;
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시상세--;
목록검색;
클릭-- > function() {
    var vIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    var vFssUnqNm = $c.stf.getObjectValue(txb_FssUnqNm);
    var vFormCd = $c.stf.getObjectValue(txb_FormCd);
    var vFormNm = $c.stf.getObjectValue(txb_FormNm);
    var vRsnclssCnt = $c.stf.getObjectValue(txb_rsn_cnt);
    var vKeyword = $c.stf.getObjectValue(txb_keyword);

    /*
    if (vKeyword == '' ) {
    	if (vIsurCd == '' &&  vFssUnqNm == '' && vFormNm == '' 
    		&& (vRsnclssCnt =='' || vRsnclssCnt == '0') ) {
    		alert("법인코드(명), 제출의무자명, 공시제목, 사유분류 중 하나 이상을  입력하셔야 합니다." );
    		txb_isur_cd.focus();
    		return;	
    	}
    } 
    */

    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }

    // 보고서코그 체크
    if (vFormCd.length > 0 && vFormCd.length != 5) {
        $c.win.alert("보고서코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) == 0 && scwin.getChkValue(chb_eng_yn) == 0) {
        $c.win.alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return;
    }

    // 제출유형 체크
    if (scwin.getChkValue(chb_main_yn) == 0 && scwin.getChkValue(chb_atch_yn) == 0) {
        $c.win.alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    if (scwin.fn_chkAttchKeyword() == false) {
        return;
    }
    var sRsnClssCdList = "";
    var sFormUpclssCd;
    var sRsnClssCd;
    for (var i = 1; i <= dts_Dscl_Cond.getTotalRow(); i++) {
        sFormUpclssCd = dts_Dscl_Cond.getCellData(i, "FORM_UPCLSS_CD");
        sRsnClssCd = dts_Dscl_Cond.getCellData(i, "RSN_CLSS_CD");
        if (sRsnClssCd != "000") {
            sRsnClssCdList += (sFormUpclssCd + sRsnClssCd + ",");
        }
    }

    // 맨뒤에 ", " 제거 하기 
    scwin.gRsnClssCdList = sRsnClssCdList.substr(0, sRsnClssCdList.length - 1);
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    if (scwin.gDepCd == "UPTEAM" && js_dep_cd.substr(2, 4) == '00') {
        scwin.gUpDepCd = js_dep_cd;
    }
    if (js_dep_cd == '3410') {
        // 코 공시제도팀인 공시총괄팀으로 설정-- 2010.03.11
        scwin.gUpDepCd = '3400';
    }
    fn_Search();
} < !공시상세--;
클릭-- > function() {
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(true);
    btn_Search.src = "../img/btn_select_d.gif";
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();
    var url = "";
    var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + $c.stf.getObjectValue(cmb_ByPass) + "&AFFPROCS_YN=" + $c.stf.getObjectValue(cmb_AffProcs) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&KEYWORD=" + $c.ut.replaceAll($c.stf.getObjectValue(txb_keyword), "&", "＆") + "&FSS_UNQ_NO=" + $c.stf.getObjectValue(txb_FssUnqNo) + "&FSS_UNQ_NM=" + $c.stf.getObjectValue(txb_FssUnqNm) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&IND_TP=" + $c.stf.getObjectValue(cmb_IndTp) + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + $c.stf.getObjectValue(cmb_Basis) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(url_cond);

    scwin.gKeyword = $c.stf.getObjectValue(txb_keyword);
    if (scwin.gKeyword.length > 0) {
        //본문검색 키워드가있을때 ... 
        var iOpCnt = 0;
        if (scwin.gKeyword.indexOf("&") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("|") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("!") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (iOpCnt > 1) {
            $c.win.alert("본문검색 키워드는 한 개만 사용할 수 있습니다.");
            txb_keyword.focus();
            return;
        }
        if (scwin.pageSize == 0) {
            $c.win.alert("공시본문내용으로 검색할 경우에는 한페이지당 보여주는 갯수를 '전체'로 사용할 수 없습니다.");
            $c.stf.setObjectValue(cmb_PerPage, "50");
            cmb_PerPage.focus();
            return;
        }
        $c.stf.showObj(mgrd_Grid, true);
        $c.stf.showObj(grd_Grid, false);
        $c.cm.ShowWin(mgrd_Grid);

        // 1. 검색 건수부터 조회한다.
        url = "/DisclosureSearch.do?method=countDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=SCN_CNTSTAT_OUT";

        //alert("본문검색 카운트: "+url + url_cond);						
        dts_scn_list.DataID = encodeURI(url + url_cond);
        dts_scn_list.reset();
        var vScnCur = dts_scn_list.getCellData(dts_scn_list.getTotalRow(), "SCN_CUR");
        //alert(dts_scn_list.CountRow +", "+vScnCur);	

        if (dts_scn_list.getTotalRow() > 0) {
            // 2.  Docruzer으로 검색
            url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
            url_cond += "&SCN_NM=" + vScnCur;
            //url_cond += "&SCN_NM=discls_internal";
            //alert("본문검색: "+url + url_cond);	

            //alert("url-->"+url + url_cond);

            dts_DsclList.DataID = encodeURI(url + url_cond);
            dts_DsclList.reset();
            $c.stf.showObj(panel_scn, true);
            $c.stf.showObj(panel_combo, true);
            $c.stf.showObj(mgrd_Grid, true);
            $c.stf.showObj(grd_Grid, false);
            $c.cm.ShowWin(mgrd_Grid);
        } else {
            // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
            btn_Search.setDisabled(false);
            btn_Search.src = "../img/btn_select.gif";
            scwin.vCurrPageNo = 0;
            dts_DsclList_excel.removeAll();
            dts_DsclList.removeAll();
            //showObj(mgrd_Grid, true);	
            //showObj(grd_Grid, false);	
            $c.cm.CloseWin(0, mgrd_Grid);
        }
    } else {
        // 본문검색 키워드가 없을때 ... 일반 DB검색
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
        dts_DsclList.DataID = encodeURI(url + url_cond);
        dts_DsclList.reset();
        $c.stf.showObj(panel_scn, false);
        $c.stf.showObj(panel_combo, false);
        $c.stf.showObj(mgrd_Grid, false);
        $c.stf.showObj(grd_Grid, true);
        $c.cm.ShowWin(grd_Grid);
    }
};
scwin.ScnarioNmCall = function(pScnNm) {
    scwin.vCurrPageNo = 0;
    var url = "";
    if (scwin.gKeyword.length > 0) {
        //본문검색 키워드가있을때 ... 

        // 2.  Docruzer으로 검색
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    } else {
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    }
    url = url + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + $c.stf.getObjectValue(cmb_ByPass) + "&AFFPROCS_YN=" + $c.stf.getObjectValue(cmb_AffProcs) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&KEYWORD=" + $c.ut.replaceAll($c.stf.getObjectValue(txb_keyword), "&", "＆") + "&FSS_UNQ_NO=" + $c.stf.getObjectValue(txb_FssUnqNo) + "&FSS_UNQ_NM=" + $c.stf.getObjectValue(txb_FssUnqNm) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&IND_TP=" + $c.stf.getObjectValue(cmb_IndTp) + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&SCN_NM=" + pScnNm + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + $c.stf.getObjectValue(cmb_Basis) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert("ScnarioNmCall=> "+ url);
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();

    //var vKeyword =  getObjectValue(txb_keyword);		
    if (scwin.gKeyword.length > 0) {
        $c.cm.ShowWin(mgrd_Grid);
    } else {
        $c.cm.ShowWin(grd_Grid);
    }
};
scwin.PageNoCall = function(vPageNo) {
    //현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    var url;
    //gKeyword =  getObjectValue(txb_keyword);	

    if (scwin.gKeyword.length > 0) {
        //본문검색 키워드가있을때 ... 

        // 2.  Docruzer으로 검색
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    } else {
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    }
    url = url + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + $c.stf.getObjectValue(cmb_ByPass) + "&AFFPROCS_YN=" + $c.stf.getObjectValue(cmb_AffProcs) + "&FORM_CD=" + $c.stf.getObjectValue(txb_FormCd) + "&FORM_NM=" + $c.stf.getObjectValue(txb_FormNm) + "&KEYWORD=" + $c.ut.replaceAll($c.stf.getObjectValue(txb_keyword), "&", "＆") + "&FSS_UNQ_NO=" + $c.stf.getObjectValue(txb_FssUnqNo) + "&FSS_UNQ_NM=" + $c.stf.getObjectValue(txb_FssUnqNm) + "&ACNTCLS_MM=" + $c.stf.getObjectValue(cmb_month) + "&IND_TP=" + $c.stf.getObjectValue(cmb_IndTp) + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&SCN_NM=" + scwin.gScnNm + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + $c.stf.getObjectValue(cmb_Basis) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_DsclList.DataID = encodeURI(url);
    dts_DsclList.reset();

    //alert("PageNoCall=> "+ url);
    //var vKeyword =  getObjectValue(txb_keyword);		
    if (scwin.gKeyword.length > 0) {
        $c.cm.ShowWin(mgrd_Grid);
    } else {
        $c.cm.ShowWin(grd_Grid);
    }
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시상세검색--;
엑셀다운로드-- > function() {
    var vKeyword = $c.stf.getObjectValue(txb_keyword);
    if (vKeyword.length > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
