scwin.fn_resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        scwin.gDepCd = "UPTEAM";
        $c.stf.setObjectValue(cmb_TeamList, scwin.gDepCd);
    }
    $c.stf.setObjectValue(txb_isur_cd, "");
    $c.stf.setObjectValue(txb_com_abbrv, "");
    $c.stf.setObjectValue(edt_FromDate, vCurrDate);
    $c.stf.setObjectValue(edt_ToDate, vCurrDate);
    $c.stf.setObjectValue(cmb_EmpList, "");
    scwin.setChkValue(chb_ListStatCd, false);
    scwin.setChkValue(chb_Last, false);
    $c.stf.setObjectValue(txb_FormCd, "");
    $c.stf.setObjectValue(txb_FormNm, "");
    $c.stf.setObjectValue(txb_keyword, "");
    $c.stf.setObjectValue(txb_FssUnqNo, "");
    $c.stf.setObjectValue(txb_FssUnqNm, "");
    $c.stf.setObjectValue(cmb_month, "");
    $c.stf.setObjectValue(cmb_IndTp, "");
    scwin.setChkValue(chb_kor_yn, true);
    scwin.setChkValue(chb_eng_yn, true);
    $c.stf.setObjectValue(rdo_MKT_ID, js_market);
    scwin.setChkValue(chb_main_yn, true);
    scwin.setChkValue(chb_atch_yn, true);
    scwin.setChkValue(chb_dep_tp, true);
    $c.stf.setObjectValue(cmb_Basis, "2");
    $c.stf.setObjectValue(cmb_PerPage, "50");
    $c.stf.setObjectValue(txb_rsn_cnt, "");
    dts_Dscl_Cond.removeAll();
    scwin.gRsnClssCdList = "";
};


// 공시팀 전체 목록에 추가
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};



// 첨부서류만 선택하고 본문검색을 하고자할때 알림.
scwin.fn_chkAttchKeyword = function() {
    var vKeyword = $c.stf.getObjectValue(txb_keyword);
    if (vKeyword.length > 0) {
        if (scwin.getChkValue(chb_main_yn) == 0 &&
            scwin.getChkValue(chb_atch_yn) == 1) {
            $c.win.alert('첨부서류만 선택한 후에는 공시본문내용 검색기능을 사용 할 수 없습니다.\n공시본문에서만 내용검색이 가능합니다.');
            txb_keyword.focus();
            return false;
        }
    }
};
