    	if (window.event.keyCode ==13){
    		fn_com_Confirm_set();
    	}else{
    		fn_com_isur_nm(window.event.keyCode);
    	}
    }
    */
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_FormCd_onblur = function() {
    if (txb_FormCd.getValue() == "") {
        txb_FormNm.setValue("");
    }
};
scwin.txb_FormNm_onblur = function() {
    if (txb_FormNm.getValue() == "") {
        txb_FormCd.setValue("");
    }
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.cmb_ByPass_OnSelChange = function() {
    var vValue = $c.cp.valueOfIndex(cmb_ByPass, "VALUE", cmb_ByPass.getSelectedIndex());
    if (vValue == '1') {
        // 전체일때 제외한 나머지경우
        cmb_AffProcs.setDisabled(false);
    } else {
        cmb_AffProcs.setDisabled(true);
    }
};
scwin.gform_onload = function() {
    $c.stf.showObj(grd_Grid_excel, false);
    $c.stf.showObj(mgrd_Grid_excel, false);
    $c.stf.showObj(panel_scn, false);
    $c.stf.showObj(panel_combo, false);
    $c.stf.showObj(mgrd_Grid, false);
    $c.stf.showObj(txb_FssUnqNo, false);

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    $c.stf.Combo_CBDataSetLimit(cmb_PerPage);
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    // 가우스헤더 셋팅
    dts_Dscl_Cond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLDETAILCOND_IN";
    dts_Dscl_Cond.reset();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
    showload.style.display = "none";
};
